mapper.select:
                SELECT T0.FINPROD_ID AS FINPRODID,
		               T0.FINPROD_NAME AS FINPRODNAME,
		               T0.PROFIT_TYPE AS FINPRODTYPE,
		               t2.val_date AS VALDATE,
		               IFNULL(T2.BUILD_STATUS, '0') AS BUILDSTATUS,
		               T2.ERROR_TYPE AS ERRORTYPE
		          from FIN_PRODUCT T0
		          inner JOIN BOK_VALBAL_TABLE_LOG T2
		            ON T0.FINPROD_ID = T2.FINPROD_ID
		           AND T2.VAL_BAL_FLAG = #{fileType}
		         where 1 = 1
		           AND T0.FINPROD_TYPE = #{finprodType}

			  			AND T0.FINPROD_ID in 

			        	#{prdId} 



			  		AND T0.PROFIT_TYPE in 

			        	#{prodType} 



					 	and t2.val_date >= #{valDateBegin,jdbcType=DATE} 


						and t2.val_date <= #{valDateEnd,jdbcType=DATE} 


			  			AND IFNULL(T2.BUILD_STATUS, '0') in 

			        		#{buildStatus} 


		           order by t2.VAL_DATE desc

select prd.finprod_id,IFNULL(prd.finprod_abbr,prd.finprod_name) finprod_abbr from fin_product prd 
	where 1=1

	AND prd.FINPROD_TYPE = #{finprodType}

    SELECT 
	    FP.FINPROD_ID AS finProdId,
	    FP.FINPROD_NAME AS finprodName,
	    A.BOOKSET_ID booksetId, 
	    A.BAL_DATE balDate,
	    A.O_CCY oCcy,
	    B.VOUCH_NUM errorCount
    FROM
(SELECT
BTD.BOOKSET_ID,
BTD.BAL_DATE,
BTD.O_CCY,
SEQ
FROM
(
/* 子查询必加上rn字段 */
SELECT result.* FROM (
SELECT tmp.*,
@rownum := @rownum + 1 row, /* 虚拟列行标 */
IF(
(
@BOOKSET_ID = tmp.BOOKSET_ID and
@BAL_DATE = tmp.BAL_DATE and
@O_CCY = tmp.O_CCY
),
@rank := @rank + 1,
@rank := 1
) AS SEQ, /* 分组虚拟列行标 */
/* 下面的分组条件需要与oracle中 over (PARTITION BY xxx,xxx,xxx)顺序保持一至 */
@BOOKSET_ID := tmp.BOOKSET_ID /* 分组条件1 */
, @BAL_DATE := tmp.BAL_DATE /* 分组条件2 */
, @O_CCY := tmp.O_CCY /* 分组条件5 */
FROM (
/* 数据源 */
SELECT bc.*
FROM BOK_BAL_TABLE_DATA bc
ORDER BY CAST(bc.BOOKSET_ID as SIGNED),CAST(bc.BAL_DATE as SIGNED),CAST(bc.O_CCY as SIGNED) DESC /* 按实际情况与oracle保持一至的排序 */
) tmp,
/* 定义临时变量池 */
(SELECT @rownum := 0,
@BOOKSET_ID := null,
@BAL_DATE = null,
@O_CCY = null,
@rank := 0) a
) result
) BTD
WHERE
1=1

	 AND BTD.BAL_DATE >= #{valDateBegin,jdbcType=DATE} 


	 AND BTD.BAL_DATE <= #{valDateEnd,jdbcType=DATE} 

) A
	LEFT JOIN BOK_VOUCH_MAIN_ERROR B ON A.BOOKSET_ID = B.BOOKSET_ID
	AND A.BAL_DATE = B.BOOK_DATE
	JOIN BOK_BOOKSET BB ON A.BOOKSET_ID = BB.BOOKSET_ID                                                                     
 	JOIN FIN_PRODUCT FP ON BB.ACCT_SUBJECT_ID = FP.FINPROD_ID
	where A.SEQ = '1'

		 AND FP.FINPROD_ID = #{prodId} 

	order by A.BOOKSET_ID, A.BAL_DATE, A.O_CCY

        SELECT COUNT(1) FROM BOK_VALBAL_TABLE_STATUS 
        WHERE 1=1

   			AND FINPROD_ID = #{prodId} 


         AND VAL_DATE>= STR_TO_DATE(#{valDateBegin},'%Y-%m-%d') 


         AND VAL_DATE<= STR_TO_DATE(#{valDateEnd},'%Y-%m-%d') 	

		AND CHECK_STATUS = #{checkStatus} 
		AND VAL_BAL_FLAG = #{fileType}
